mapper.delete:
DELETE FROM t_phase_one_feedback_cluster_identity_projection
WHERE generation_id=#{generationId} AND source_id IN
#{sourceId}

mapper.select:
SELECT generation_id,source_id,cluster_id,source_channel,logical_channel,function_module,province_code,
       city_code,region_value,reported_at,identity_scope,identity_type,fingerprint_key_id,fingerprint
FROM t_phase_one_feedback_cluster_identity_projection
WHERE generation_id=#{generationId}
  AND (source_id>#{afterSourceId} OR (source_id=#{afterSourceId}
    AND CONCAT(identity_scope,':',identity_type,':',fingerprint_key_id,':',HEX(fingerprint))>#{afterIdentityKey}))
ORDER BY source_id,identity_scope,identity_type,fingerprint_key_id,fingerprint
LIMIT #{limit}
